{"path":"fees.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Fees & Packages — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Transparent fee options for short-focused work and time-limited intensives. Clear boundaries, confidentiality, and the clinician's way of planning care.">
  <style>
    :root{--bg:#fbfbfc;--muted:#6b7280;--accent:#6b3b9b;--card:#fff;--glass:rgba(255,255,255,0.6);--shadow:0 8px 24px rgba(23,23,23,0.08);font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial}
    html,body{height:100%}
    body{margin:0;background:linear-gradient(180deg,var(--bg),#fff);color:#0f172a}
    header{background:linear-gradient(180deg,rgba(107,59,155,0.08),transparent);padding:28px 20px;border-bottom:1px solid rgba(15,23,42,0.04);position:sticky;top:0;backdrop-filter:blur(6px)}
    .wrap{max-width:980px;margin:0 auto}
    nav{display:flex;gap:18px;align-items:center;flex-wrap:wrap}
    .brand{font-weight:700;color:var(--accent)}
    nav a{color:#0f172a;text-decoration:none;padding:8px 10px;border-radius:8px}
    nav a.cta{background:var(--accent);color:#fff}
    main{padding:36px 20px}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;align-items:center}
    .hero h1{margin:0;font-size:28px}
    .lead{color:var(--muted);max-width:70ch}
    .cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin-top:18px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:var(--shadow);border:1px solid rgba(15,23,42,0.03)}
    .price{font-weight:700;font-size:20px;color:var(--accent)}
    .note{font-size:13px;color:var(--muted)}
    .small{font-size:13px;color:var(--muted);margin-top:8px}
    footer{padding:28px 20px;border-top:1px solid rgba(15,23,42,0.04);text-align:center;color:var(--muted)}
    .try-btn{background:#fff;border:1px solid rgba(15,23,42,0.06);padding:10px 14px;border-radius:10px;cursor:pointer}
    /* reveal */
    .reveal{opacity:0;transform:translateY(16px);transition:opacity .6s var(--e,ease),transform .6s var(--e,ease)}
    .reveal.visible{opacity:1;transform:none}
    /* modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(3,7,18,0.45);display:none;align-items:center;justify-content:center;padding:20px}
    .modal{background:linear-gradient(180deg,#fff,rgba(255,255,255,0.96));width:100%;max-width:720px;border-radius:12px;padding:20px;box-shadow:0 20px 40px rgba(2,6,23,0.4)}
    .modal h2{margin:0 0 6px}
    .modal .controls{display:flex;gap:10px;align-items:center;margin-top:12px}
    .breath-circle{width:120px;height:120px;border-radius:50%;margin:10px auto;background:radial-gradient(circle at 30% 30%,rgba(107,59,155,0.14),rgba(107,59,155,0.04));display:flex;align-items:center;justify-content:center;font-weight:600;color:var(--accent)}
    .sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
    @media(min-width:700px){.hero{grid-template-columns:1fr 340px}}
  </style>
</head>
<body>
  <header>
    <div class="wrap">
      <nav aria-label="Primary navigation">
        <div class="brand">{{BUSINESS_NAME}}</div>
        <a href="index.html">Home</a>
        <a href="about.html">Meet</a>
        <a href="specialties.html">Services</a>
        <a href="approach.html">Approach</a>
        <a href="fees.html" aria-current="page">Investment</a>
        <a href="faq.html">Questions</a>
        <a href="book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
    </div>
  </header>

  <main class="wrap">
    <section class="hero reveal" id="overview">
      <div>
        <h1>Clear options for brief and focused work</h1>
        <p class="lead">I offer time-limited packages and single sessions designed to help you address a specific issue, make a targeted plan, or reduce immediate overwhelm. Below are practical tiers to match different goals and rhythms.</p>
        <div style="margin-top:12px">
          <button class="try-btn" id="open-guided">Try a short guided exercise</button>
        </div>
      </div>
      <aside class="card reveal" style="--e:cubic-bezier(.16,.84,.44,1)">
        <div style="font-size:13px;color:var(--muted)">Availability</div>
        <div style="margin-top:8px">
          <div class="price">Standard session: $165</div>
          <div class="small">50-minute psychotherapeutic session — telehealth or in-person by arrangement.</div>
        </div>
        <div style="margin-top:12px">
          <div class="price">New-client intake: $195</div>
          <div class="small">Comprehensive intake, goal-setting, and collaborative treatment planning.</div>
        </div>
      </aside>
    </section>

    <section class="cards" aria-label="Packages">
      <article class="card reveal" id="package-1">
        <h3>Focused Path (4 sessions)</h3>
        <div class="price">$620</div>
        <p class="small">A short sequence for specific choices, problem-solving, or to gather momentum. Includes a brief written plan after the final session.</p>
        <div class="note">Recommended cadence: weekly or biweekly. Does not replace ongoing therapy when longer-term work is needed.</div>
      </article>

      <article class="card reveal" id="package-2">
        <h3>Weekend Intensive (4 hours)</h3>
        <div class="price">$720</div>
        <p class="small">A concentrated block for focused review—goal formation, coping tools, and next steps. Conducted over a single afternoon or two shorter blocks.</p>
        <div class="note">Not appropriate in a crisis. Intake required prior to booking.</div>
      </article>

      <article class="card reveal" id="package-3">
        <h3>Care Plan Session (single extended)</h3>
        <div class="price">$220</div>
        <p class="small">Longer, 75-minute session to create an actionable care plan and short-term strategies. Good for transitions or planning a next phase.</p>
        <div class="note">Follow-up options available; recommended for folks seeking structure without ongoing weekly work.</div>
      </article>
    </section>

    <section class="card reveal" style="margin-top:18px">
      <h3>Billing, Insurance, and Practicalities</h3>
      <p class="small">I am a private-pay clinician. I can provide a superbill you may submit to your insurance for out-of-network reimbursement. Payments are due at time of service. I accept card and electronic transfer.</p>
      <p class="small">Cancellations with less than 48 hours' notice may incur a fee.</p>
    </section>

    <section class="card reveal" style="margin-top:18px">
      <h3>Clinical boundaries & safety</h3>
      <p class="small">Sessions are confidential within the limits of the law. I will review limits to confidentiality during intake. I do not provide emergency crisis services; if you are in crisis or at risk of harm, please call local emergency services or a crisis line immediately.</p>
      <p class="small">My scope is psychotherapy for adults. When other supports are needed (medical, legal, or emergency), I will help coordinate referrals.</p>
    </section>

    <div style="margin-top:18px;display:flex;gap:12px;flex-wrap:wrap">
      <a href="book.html" class="try-btn">Schedule a consultation</a>
      <a href="faq.html" class="try-btn">Read practical FAQs</a>
    </div>
  </main>

  <footer>
    <div class="wrap">
      <div class="small">Contact: <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      <div class="small" style="margin-top:6px">Licensed clinician. Services offered in {{CITY}}, {{STATE}}. Confidentiality and limits discussed in intake.</div>
    </div>
  </footer>

  <!-- Modal guided exercise -->
  <div class="modal-backdrop" id="modal" role="dialog" aria-modal="true" aria-hidden="true">
    <div class="modal" role="document">
      <button id="close-modal" aria-label="Close" style="float:right;background:none;border:0;font-size:16px;cursor:pointer">✕</button>
      <h2 id="modal-title">Short Practice — Choose a path</h2>
      <p class="small">A brief guided exercise you can use in a quiet moment. Choose one: breathing, journaling, or intention-setting. No data is stored.</p>

      <div id="choices" style="display:flex;gap:8px;margin-top:12px">
        <button data-mode="breath" class="try-btn">Breathing</button>
        <button data-mode="journal" class="try-btn">Journaling</button>
        <button data-mode="intend" class="try-btn">Set Intention</button>
      </div>

      <div id="exercise" style="margin-top:16px"></div>

      <div style="margin-top:14px;display:flex;gap:8px;justify-content:flex-end">
        <button id="modal-done" class="try-btn">Close</button>
      </div>
    </div>
  </div>

  <script>
    (function(){
      // scroll reveal with reduced motion support
      const prefersReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const revealNodes = document.querySelectorAll('.reveal');
      if(prefersReduced){
        revealNodes.forEach(n=>n.classList.add('visible'));
      } else if('IntersectionObserver' in window){
        const io = new IntersectionObserver((entries, obs)=>{
          entries.forEach(e=>{
            if(e.isIntersecting){
              e.target.classList.add('visible');
              obs.unobserve(e.target);
            }
          });
        },{threshold:0.12});
        revealNodes.forEach(n=>io.observe(n));
      } else {
        revealNodes.forEach(n=>n.classList.add('visible'));
      }

      // Modal guided exercise
      const modal = document.getElementById('modal');
      const openBtn = document.getElementById('open-guided');
      const closeBtn = document.getElementById('close-modal');
      const doneBtn = document.getElementById('modal-done');
      const choices = document.getElementById('choices');
      const exercise = document.getElementById('exercise');

      function showModal(){ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); document.body.style.overflow='hidden'; document.getElementById('modal-title').focus && document.getElementById('modal-title').focus(); }
      function hideModal(){ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); document.body.style.overflow=''; exercise.innerHTML=''; }

      openBtn.addEventListener('click', showModal);
      closeBtn.addEventListener('click', hideModal);
      doneBtn.addEventListener('click', hideModal);

      choices.addEventListener('click', function(e){
        const mode = e.target.getAttribute('data-mode');
        if(!mode) return;
        exercise.innerHTML='';
        if(mode==='breath') renderBreath();
        if(mode==='journal') renderJournal();
        if(mode==='intend') renderIntend();
      });

      function renderBreath(){
        const container = document.createElement('div');
        container.innerHTML = '<div class="breath-circle" id="circle">Breathe</div><div style="text-align:center;color:var(--muted);margin-top:8px">Follow the inhale / exhale prompts below.</div>';
        const controls = document.createElement('div'); controls.className='controls';
        const start = document.createElement('button'); start.textContent='Start 1 min'; start.className='try-btn';
        const stop = document.createElement('button'); stop.textContent='Stop'; stop.className='try-btn';
        controls.appendChild(start); controls.appendChild(stop);
        container.appendChild(controls);
        exercise.appendChild(container);

        let running=false, timer=null, phase=0;
        const phases = [ {text:'Inhale',ms:4000}, {text:'Hold',ms:1200}, {text:'Exhale',ms:6000}, {text:'Rest',ms:1200} ];
        const circle = container.querySelector('#circle');

        function step(){
          const p = phases[phase%phases.length];
          circle.textContent = p.text;
          circle.style.transform = p.text==='Inhale'? 'scale(1.15)': p.text==='Exhale'? 'scale(.95)': 'scale(1)';
          phase++;
          if(running) timer = setTimeout(step, p.ms);
        }
        start.addEventListener('click', ()=>{ if(running) return; running=true; step(); });
        stop.addEventListener('click', ()=>{ running=false; clearTimeout(timer); circle.textContent='Breathe'; circle.style.transform='scale(1)'; });
      }

      function renderJournal(){
        const container = document.createElement('div');
        container.innerHTML = '<label style="display:block;font-weight:600;margin-bottom:6px">A quick writing prompt</label>';
        const prompt = document.createElement('div'); prompt.className='small'; prompt.textContent = 'Write for 6 minutes: What feels most alive right now? What would I like to notice more of?';
        const ta = document.createElement('textarea'); ta.rows=8; ta.style.width='100%'; ta.style.marginTop='8px'; ta.style.padding='10px'; ta.placeholder='Write here (not saved)...';
        const quick = document.createElement('div'); quick.style.marginTop='8px'; quick.innerHTML = '<button class="try-btn">Start 6-minute timer</button> <span style="color:var(--muted);margin-left:8px">You can close when finished.</span>';
        const btn = quick.querySelector('button');
        let t=null, endAt=0;
        const timerDisplay = document.createElement('div'); timerDisplay.className='small'; timerDisplay.style.marginTop='8px';
        btn.addEventListener('click', ()=>{
          clearInterval(t); let remaining=360; endAt = Date.now()+remaining*1000; timerDisplay.textContent = '6:00';
          t = setInterval(()=>{
            remaining = Math.max(0, Math.round((endAt-Date.now())/1000));
            const mm = Math.floor(remaining/60); const ss = String(remaining%60).padStart(2,'0');
            timerDisplay.textContent = mm+':'+ss;
            if(remaining<=0){ clearInterval(t); timerDisplay.textContent='Done'; }
          },250);
        });
        container.appendChild(prompt); container.appendChild(ta); container.appendChild(quick); container.appendChild(timerDisplay);
        exercise.appendChild(container);
      }

      function renderIntend(){
        const container = document.createElement('div');
        container.innerHTML = '<label style="font-weight:600">Set a short intention</label><div class="small" style="margin-top:8px">Choose one phrase to carry with you today; keep it simple.</div>';
        const list = ['I will notice what I need','I will pause before deciding','I will breathe before reacting','I will name one small action'];
        const ul = document.createElement('div'); ul.style.marginTop='8px'; ul.style.display='grid'; ul.style.gridTemplateColumns='1fr 1fr'; ul.style.gap='8px';
        list.forEach(text=>{ const b=document.createElement('button'); b.className='try-btn'; b.textContent=text; b.addEventListener('click', ()=>{ container.innerHTML='<div style="font-weight:600">Your intention</div><div style="margin-top:8px;font-size:18px;color:var(--accent)">'+text+'</div><div class="small" style="margin-top:8px">Try returning to this phrase three times today.</div>'; }); ul.appendChild(b); });
        container.appendChild(ul);
        exercise.appendChild(container);
      }

      // close modal on backdrop click
      modal.addEventListener('click', function(e){ if(e.target===modal) hideModal(); });
    })();
  </script>
</body>
</html>"} 
