<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQ — Common Questions — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Practical answers about therapy format, confidentiality, boundaries, and booking. Relevant to people exploring short-term work or focused plans.">
  <style>
    :root{--bg:#fff;--muted:#6b7280;--accent:#6b3b9b;--card:#fff;--shadow:0 10px 30px rgba(15,23,42,0.06);font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial}
    body{margin:0;background:linear-gradient(180deg,#fff,#fbfbff);color:#0f172a}
    .wrap{max-width:900px;margin:0 auto;padding:28px 20px}
    header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}
    nav a{margin-left:10px;color:#0f172a;text-decoration:none}
    h1{margin:0 0 6px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .faq-item{background:var(--card);padding:16px;border-radius:10px;box-shadow:var(--shadow);border:1px solid rgba(15,23,42,0.03)}
    .q{font-weight:700}
    .a{color:var(--muted);margin-top:8px}
    .aside-card{background:linear-gradient(180deg,rgba(107,59,155,0.04),transparent);padding:16px;border-radius:10px}
    .try-btn{background:#fff;border:1px solid rgba(15,23,42,0.06);padding:10px 12px;border-radius:10px;cursor:pointer}
    .reveal{opacity:0;transform:translateY(14px);transition:opacity .5s ease,transform .5s ease}
    .reveal.visible{opacity:1;transform:none}
    footer{margin-top:18px;color:var(--muted);font-size:13px}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div>
        <div style="font-weight:700;color:var(--accent)">{{BUSINESS_NAME}}</div>
        <div class="small">Compassionate clinical work in {{CITY}}, {{STATE}}</div>
      </div>
      <nav>
        <a href="index.html">Home</a>
        <a href="about.html">Meet</a>
        <a href="specialties.html">Areas</a>
        <a href="fees.html">Investment</a>
        <a href="contact.html">Contact</a>
        <a href="book.html">Book</a>
      </nav>
    </header>

    <main class="grid">
      <section>
        <h1 class="reveal">Common questions</h1>
        <p class="reveal" style="color:var(--muted)">Answers framed to help you choose whether to begin. If you still have concerns, booking a short consult can clarify fit.</p>

        <div class="faq-item reveal" style="margin-top:12px">
          <div class="q">What is the typical format?</div>
          <div class="a">Most work happens in 50-minute sessions. I also offer extended single sessions and structured short packages. We’ll agree on goals and cadence at intake.</div>
        </div>

        <div class="faq-item reveal" style="margin-top:12px">
          <div class="q">Do you take insurance?</div>
          <div class="a">I am private-pay and can provide a superbill for you to submit to your insurer for possible reimbursement. If using insurance is essential, I can discuss referrals.</div>
        </div>

        <div class="faq-item reveal" style="margin-top:12px">
          <div class="q">How confidential is therapy?</div>
          <div class="a">Sessions are confidential within legal limits. Exceptions include imminent risk of harm to self or others, abuse of a minor, elder abuse, or a court order. I review confidentiality and limits during the intake process.</div>
        </div>

        <div class="faq-item reveal" style="margin-top:12px">
          <div class="q">What if I’m in crisis?</div>
          <div class="a">If you are in immediate danger or at risk of harming yourself or others, call emergency services or your local crisis hotline. I do not provide emergency services; for urgent mental health needs use local crisis resources or 988 (US).</div>
        </div>

        <div class="faq-item reveal" style="margin-top:12px">
          <div class="q">What should I expect in the first session?</div>
          <div class="a">We review your concerns, your history relevant to the presenting problem, and collaboratively create a focused plan with clear next steps. You can expect a gentle but structured conversation aimed at clarity and safety.</div>
        </div>

        <div class="faq-item reveal" style="margin-top:12px">
          <div class="q">How long will therapy take?</div>
          <div class="a">There is no fixed timeline. Some people find brief, targeted packages helpful; others choose ongoing work. We’ll revisit goals and pacing regularly and adjust as needed.</div>
        </div>
      </section>

      <aside class="aside-card reveal">
        <h3>Quick actions</h3>
        <p class="small">If you’re deciding now, a short consult can help you choose the right entry point.</p>
        <div style="margin-top:12px;display:flex;gap:8px;flex-direction:column">
          <a href="book.html" class="try-btn">Book a 20-minute consult</a>
          <button class="try-btn" id="open-guided">Try a calming practice</button>
          <a href="fees.html" class="try-btn">See fees</a>
        </div>

        <div style="margin-top:14px;font-size:13px;color:var(--muted)">
          Confidentiality and boundaries are discussed at intake. For emergencies, call local emergency services or your crisis line.
        </div>
      </aside>
    </main>

    <footer>
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap">
        <div style="color:var(--muted)">Questions? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
        <div style="color:var(--muted)">Practice serves adults in {{CITY}}, {{STATE}}.</div>
      </div>
    </footer>
  </div>

  <!-- Modal (same guided exercise used here) -->
  <div class="modal-backdrop" id="modal" role="dialog" aria-modal="true" aria-hidden="true" style="display:none;align-items:center;justify-content:center;padding:20px">
    <div class="modal" role="document" style="max-width:720px;background:#fff;padding:20px;border-radius:12px;box-shadow:0 20px 40px rgba(2,6,23,0.4)">
      <button id="close-modal" aria-label="Close" style="float:right;background:none;border:0;font-size:16px;cursor:pointer">✕</button>
      <h2 id="modal-title">Short Practice</h2>
      <p class="small">Choose breathing, journaling, or a simple intention. No data is kept.</p>
      <div id="choices" style="display:flex;gap:8px;margin-top:12px">
        <button data-mode="breath" class="try-btn">Breathing</button>
        <button data-mode="journal" class="try-btn">Journaling</button>
        <button data-mode="intend" class="try-btn">Intention</button>
      </div>
      <div id="exercise" style="margin-top:16px"></div>
      <div style="margin-top:12px;text-align:right"><button id="modal-done" class="try-btn">Close</button></div>
    </div>
  </div>

  <script>
    (function(){
      // reveal
      const prefersReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const elements = document.querySelectorAll('.reveal');
      if(prefersReduced){ elements.forEach(e=>e.classList.add('visible')); }
      else if('IntersectionObserver' in window){
        const io = new IntersectionObserver((entries,obs)=>{ entries.forEach(en=>{ if(en.isIntersecting){ en.target.classList.add('visible'); obs.unobserve(en.target); } }); },{threshold:0.08});
        elements.forEach(e=>io.observe(e));
      } else { elements.forEach(e=>e.classList.add('visible')); }

      // reuse modal logic from fees page simple version
      const modal = document.getElementById('modal');
      const openBtn = document.getElementById('open-guided');
      const closeBtn = document.getElementById('close-modal');
      const doneBtn = document.getElementById('modal-done');
      const choices = document.getElementById('choices');
      const exercise = document.getElementById('exercise');

      function showModal(){ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); document.body.style.overflow='hidden'; }
      function hideModal(){ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); document.body.style.overflow=''; exercise.innerHTML=''; }

      if(openBtn) openBtn.addEventListener('click', showModal);
      if(closeBtn) closeBtn.addEventListener('click', hideModal);
      if(doneBtn) doneBtn.addEventListener('click', hideModal);

      choices.addEventListener('click', function(e){
        const mode = e.target.getAttribute('data-mode');
        if(!mode) return; exercise.innerHTML='';
        if(mode==='breath') exercise.innerHTML = '<div style="text-align:center;font-weight:600;color:var(--accent)">Inhale — Hold — Exhale</div><div style="margin-top:8px;color:var(--muted)">Click start below. Follow the prompts for about one minute.</div><div style="text-align:center;margin-top:10px"><button class="try-btn" id="start-b">Start</button><button class="try-btn" id="stop-b" style="margin-left:8px">Stop</button></div><div id="circle" style="width:120px;height:120px;border-radius:50%;margin:12px auto;background:radial-gradient(circle at 30% 30%,rgba(107,59,155,0.12),rgba(107,59,155,0.02));display:flex;align-items:center;justify-content:center;font-weight:600;color:var(--accent)">Breathe</div>';
        if(mode==='journal') exercise.innerHTML = '<div style="font-weight:600">Quick prompt</div><div style="color:var(--muted);margin-top:8px">Spend a few minutes writing: What do I need to notice right now?</div><textarea rows="6" style="width:100%;margin-top:8px;padding:10px" placeholder="Write here (not saved)..."></textarea>';
        if(mode==='intend') exercise.innerHTML = '<div style="font-weight:600">Pick one phrase to guide the next hour</div><div style="display:flex;gap:8px;margin-top:8px"><button class="try-btn">Stay curious</button><button class="try-btn">One small step</button><button class="try-btn">Pause then act</button></div>';
      });

      // simple breathing controls
      document.addEventListener('click', function(e){
